def _join_i8_wrapper(joinf, with_indexers: bool = True):
    """
   Create the join wrapper methods.
    """

   @staticmethod  # type: ignore
   def wrapper(left, right):
       if isinstance(left, (np.ndarray, ABCIndex, ABCSeries, DatetimeLikeArrayMixin)):
           left = left.view("i8")
       if isinstance(right, (np.ndarray, ABCIndex, ABCSeries, DatetimeLikeArrayMixin)):
           right = right.view("i8")

       results = joinf(left, right)
       if with_indexers:
           # dtype should be timedelta64[ns] for TimedeltaIndex
           #  and datetime64[ns] for DatetimeIndex
           dtype = left.dtype.base

           join_index, left_indexer, right_indexer = results
           join_index = join_index.view(dtype)
           return join_index, left_indexer, right_indexer
       return results

   return wrapper


@inherit_names(
   ["inferred_freq", "_isnan", "_resolution", "resolution"],
   DatetimeLikeArrayMixin,
   cache=True,
)
@inherit_names(
   ["__iter__", "mean", "freq", "freqstr", "_ndarray_values", "asi8", "_box_values"],
   DatetimeLikeArrayMixin,
)
class DatetimeIndexOpsMixin(ExtensionIndex, ExtensionOpsMixin):
   """
   Common ops mixin to support a unified interface datetimelike Index.
   """

   _data: ExtensionArray
   freq: Optional[DateOffset]
   freqstr: Optional[str]
   _resolution: int
   _bool_ops: List[str] = []
   _field_ops: List[str] = []

   hasnans = cache_readonly(DatetimeLikeArrayMixin._hasnans.fget)  # type: ignore
   _hasnans = hasnans  # for index / array -agnostic code

    @property
   def is_all_dates(self) -> bool:
       return True

   @classmethod
   def _create_comparison_method(cls, op):
        """
       Create a comparison method that dispatches to ``cls.values``.
        """
       return make_wrapped_comparison_op(f"__{op.__name__}__")

   # ------------------------------------------------------------------------
   # Abstract data attributes

   @property
   def values(self):
       # Note: PeriodArray overrides this to return an ndarray of objects.
       return self._data._data

   def __array_wrap__(self, result, context=None):
        """
       Gets called after a ufunc.
        """
       result = lib.item_from_zerodim(result)
       if is_bool_dtype(result) or lib.is_scalar(result):
           return result

       attrs = self._get_attributes_dict()
       if not is_period_dtype(self) and attrs["freq"]:
           # no need to infer if freq is None
           attrs["freq"] = "infer"
       return Index(result, **attrs)

   # ------------------------------------------------------------------------

   def equals(self, other) -> bool:
        """
       Determines if two Index objects contain the same elements.
        """
       if self.is_(other):
           return True

       if not isinstance(other, ABCIndexClass):
           return False
       elif not isinstance(other, type(self)):
           try:
               other = type(self)(other)
           except (ValueError, TypeError, OverflowError):
               # e.g.
               #  ValueError -> cannot parse str entry, or OutOfBoundsDatetime
               #  TypeError  -> trying to convert IntervalIndex to DatetimeIndex
               #  OverflowError -> Index([very_large_timedeltas])
               return False

       if not is_dtype_equal(self.dtype, other.dtype):
           # have different timezone
           return False

       return np.array_equal(self.asi8, other.asi8)

   @Appender(_index_shared_docs["contains"] % _index_doc_kwargs)
   def __contains__(self, key):
       try:
           res = self.get_loc(key)
           return (
               is_scalar(res)
               or isinstance(res, slice)
               or (is_list_like(res) and len(res))
           )
       except (KeyError, TypeError, ValueError):
           return False

   # Try to run function on index first, and then on elements of index
   # Especially important for group-by functionality
   def map(self, mapper, na_action=None):
       try:
           result = mapper(self)

           # Try to use this result if we can
           if isinstance(result, np.ndarray):
               result = Index(result)

           if not isinstance(result, Index):
               raise TypeError("The map function must return an Index object")
           return result
       except Exception:
           return self.astype(object).map(mapper)

   def sort_values(self, return_indexer=False, ascending=True):
        """
       Return sorted copy of Index.
        """
       if return_indexer:
           _as = self.argsort()
           if not ascending:
               _as = _as[::-1]
           sorted_index = self.take(_as)
           return sorted_index, _as
       else:
           # NB: using asi8 instead of _ndarray_values matters in numpy 1.18
           #  because the treatment of NaT has been changed to put NaT last
           #  instead of first.
           sorted_values = np.sort(self.asi8)
           attribs = self._get_attributes_dict()
           freq = attribs["freq"]

           if freq is not None and not is_period_dtype(self):
               if freq.n > 0 and not ascending:
                   freq = freq * -1
               elif freq.n < 0 and ascending:
                   freq = freq * -1
           attribs["freq"] = freq

           if not ascending:
               sorted_values = sorted_values[::-1]

           return self._simple_new(sorted_values, **attribs)

   @Appender(_index_shared_docs["take"] % _index_doc_kwargs)
   def take(self, indices, axis=0, allow_fill=True, fill_value=None, **kwargs):
       nv.validate_take(tuple(), kwargs)
       indices = ensure_int64(indices)

       maybe_slice = lib.maybe_indices_to_slice(indices, len(self))
       if isinstance(maybe_slice, slice):
           return self[maybe_slice]

       return ExtensionIndex.take(
           self, indices, axis, allow_fill, fill_value, **kwargs
       )

   _can_hold_na = True

   _na_value = NaT
   """The expected NA value to use with this index."""

   def _convert_tolerance(self, tolerance, target):
       tolerance = np.asarray(to_timedelta(tolerance).to_numpy())

       if target.size != tolerance.size and tolerance.size > 1:
           raise ValueError("list-like tolerance size must match target index size")
       return tolerance

   def tolist(self) -> List:
       """
       Return a list of the underlying data.
       """
       return list(self.astype(object))

   def min(self, axis=None, skipna=True, *args, **kwargs):
       """
       Return the minimum value of the Index or minimum along
       an axis.

       See Also
        --------
       numpy.ndarray.min
       Series.min : Return the minimum value in a Series.
        """
       nv.validate_min(args, kwargs)
       nv.validate_minmax_axis(axis)

       if not len(self):
           return self._na_value

       i8 = self.asi8
       try:
           # quick check
           if len(i8) and self.is_monotonic:
               if i8[0] != iNaT:
                   return self._box_func(i8[0])

           if self.hasnans:
               if skipna:
                   min_stamp = self[~self._isnan].asi8.min()
               else:
                   return self._na_value
           else:
               min_stamp = i8.min()
           return self._box_func(min_stamp)
       except ValueError:
           return self._na_value

   def argmin(self, axis=None, skipna=True, *args, **kwargs):
        """
       Returns the indices of the minimum values along an axis.

       See `numpy.ndarray.argmin` for more information on the
       `axis` parameter.

       See Also
       --------
       numpy.ndarray.argmin
        """
       nv.validate_argmin(args, kwargs)
       nv.validate_minmax_axis(axis)

       i8 = self.asi8
       if self.hasnans:
           mask = self._isnan
           if mask.all() or not skipna:
               return -1
           i8 = i8.copy()
           i8[mask] = np.iinfo("int64").max
       return i8.argmin()

   def max(self, axis=None, skipna=True, *args, **kwargs):
        """
       Return the maximum value of the Index or maximum along
       an axis.

       See Also
       --------
       numpy.ndarray.max
       Series.max : Return the maximum value in a Series.
       """
       nv.validate_max(args, kwargs)
       nv.validate_minmax_axis(axis)

       if not len(self):
           return self._na_value

       i8 = self.asi8
       try:
           # quick check
           if len(i8) and self.is_monotonic:
               if i8[-1] != iNaT:
                   return self._box_func(i8[-1])

           if self.hasnans:
               if skipna:
                   max_stamp = self[~self._isnan].asi8.max()
               else:
                   return self._na_value
           else:
               max_stamp = i8.max()
           return self._box_func(max_stamp)
       except ValueError:
           return self._na_value

   def argmax(self, axis=None, skipna=True, *args, **kwargs):
       """
       Returns the indices of the maximum values along an axis.

       See `numpy.ndarray.argmax` for more information on the
       `axis` parameter.

       See Also
       --------
       numpy.ndarray.argmax
       """
       nv.validate_argmax(args, kwargs)
       nv.validate_minmax_axis(axis)

       i8 = self.asi8
       if self.hasnans:
           mask = self._isnan
           if mask.all() or not skipna:
               return -1
           i8 = i8.copy()
           i8[mask] = 0
       return i8.argmax()

