   # List-like Methods

   def delete(self, loc):
       new_i8s = np.delete(self.asi8, loc)

       freq = None
       if is_period_dtype(self):
           freq = self.freq
       elif is_integer(loc):
           if loc in (0, -len(self), -1, len(self) - 1):
               freq = self.freq
        else:
           if is_list_like(loc):
               loc = lib.maybe_indices_to_slice(ensure_int64(np.array(loc)), len(self))
           if isinstance(loc, slice) and loc.step in (1, None):
               if loc.start in (0, None) or loc.stop in (len(self), None):
                   freq = self.freq

       return self._shallow_copy(new_i8s, freq=freq)


class DatetimeTimedeltaMixin(DatetimeIndexOpsMixin, Int64Index):
   """
   Mixin class for methods shared by DatetimeIndex and TimedeltaIndex,
   but not PeriodIndex
   """

   # Compat for frequency inference, see GH#23789
   _is_monotonic_increasing = Index.is_monotonic_increasing
   _is_monotonic_decreasing = Index.is_monotonic_decreasing
   _is_unique = Index.is_unique

   def _set_freq(self, freq):
        """
       Set the _freq attribute on our underlying DatetimeArray.

        Parameters
        ----------
       freq : DateOffset, None, or "infer"
       """
       # GH#29843
       if freq is None:
           # Always valid
           pass
       elif len(self) == 0 and isinstance(freq, DateOffset):
           # Always valid.  In the TimedeltaIndex case, we assume this
           #  is a Tick offset.
           pass
        else:
           # As an internal method, we can ensure this assertion always holds
           assert freq == "infer"
           freq = to_offset(self.inferred_freq)

       self._data._freq = freq

   def _shallow_copy(self, values=None, **kwargs):
       if values is None:
           values = self._data
       if isinstance(values, type(self)):
           values = values._data

       attributes = self._get_attributes_dict()

       if "freq" not in kwargs and self.freq is not None:
           if isinstance(values, (DatetimeArray, TimedeltaArray)):
               if values.freq is None:
                   del attributes["freq"]

       attributes.update(kwargs)
       return self._simple_new(values, **attributes)

   # --------------------------------------------------------------------
   # Set Operation Methods

   @Appender(Index.difference.__doc__)
   def difference(self, other, sort=None):
       new_idx = super().difference(other, sort=sort)
       new_idx._set_freq(None)
       return new_idx

   def intersection(self, other, sort=False):
        """
       Specialized intersection for DatetimeIndex/TimedeltaIndex.

       May be much faster than Index.intersection

        Parameters
        ----------
       other : Same type as self or array-like
       sort : False or None, default False
           Sort the resulting index if possible.

           .. versionadded:: 0.24.0

           .. versionchanged:: 0.24.1

              Changed the default to ``False`` to match the behaviour
              from before 0.24.0.

           .. versionchanged:: 0.25.0

              The `sort` keyword is added

        Returns
        -------
       y : Index or same type as self
        """
       self._validate_sort_keyword(sort)
       self._assert_can_do_setop(other)

       if self.equals(other):
           return self._get_reconciled_name_object(other)

       if len(self) == 0:
           return self.copy()
       if len(other) == 0:
           return other.copy()

       if not isinstance(other, type(self)):
           result = Index.intersection(self, other, sort=sort)
           if isinstance(result, type(self)):
               if result.freq is None:
                   result._set_freq("infer")
           return result

       elif (
           other.freq is None
           or self.freq is None
           or other.freq != self.freq
           or not other.freq.is_anchored()
           or (not self.is_monotonic or not other.is_monotonic)
       ):
           result = Index.intersection(self, other, sort=sort)

           # Invalidate the freq of `result`, which may not be correct at
           # this point, depending on the values.

           result._set_freq(None)
           result = self._shallow_copy(
               result._data, name=result.name, dtype=result.dtype, freq=None
            )
           if result.freq is None:
               result._set_freq("infer")
           return result

       # to make our life easier, "sort" the two ranges
       if self[0] <= other[0]:
           left, right = self, other
       else:
           left, right = other, self

       # after sorting, the intersection always starts with the right index
       # and ends with the index of which the last elements is smallest
       end = min(left[-1], right[-1])
       start = right[0]

       if end < start:
           return type(self)(data=[])
       else:
           lslice = slice(*left.slice_locs(start, end))
           left_chunk = left.values[lslice]
           return self._shallow_copy(left_chunk)

   def _can_fast_union(self, other) -> bool:
       if not isinstance(other, type(self)):
           return False

       freq = self.freq

       if freq is None or freq != other.freq:
           return False

       if not self.is_monotonic or not other.is_monotonic:
           return False

       if len(self) == 0 or len(other) == 0:
           return True

       # to make our life easier, "sort" the two ranges
       if self[0] <= other[0]:
           left, right = self, other
       else:
           left, right = other, self

       right_start = right[0]
       left_end = left[-1]

       # Only need to "adjoin", not overlap
        try:
           return (right_start == left_end + freq) or right_start in left
        except ValueError:
           # if we are comparing a freq that does not propagate timezones
           # this will raise
           return False

   def _fast_union(self, other, sort=None):
       if len(other) == 0:
           return self.view(type(self))

       if len(self) == 0:
           return other.view(type(self))

       # to make our life easier, "sort" the two ranges
       if self[0] <= other[0]:
           left, right = self, other
       elif sort is False:
           # TDIs are not in the "correct" order and we don't want
           #  to sort but want to remove overlaps
           left, right = self, other
           left_start = left[0]
           loc = right.searchsorted(left_start, side="left")
           right_chunk = right.values[:loc]
           dates = concat_compat((left.values, right_chunk))
           return self._shallow_copy(dates)
        else:
           left, right = other, self

       left_end = left[-1]
       right_end = right[-1]

       # concatenate
       if left_end < right_end:
           loc = right.searchsorted(left_end, side="right")
           right_chunk = right.values[loc:]
           dates = concat_compat((left.values, right_chunk))
           return self._shallow_copy(dates)
        else:
           return left

   def _union(self, other, sort):
       if not len(other) or self.equals(other) or not len(self):
           return super()._union(other, sort=sort)

       # We are called by `union`, which is responsible for this validation
       assert isinstance(other, type(self))

       this, other = self._maybe_utc_convert(other)

       if this._can_fast_union(other):
           return this._fast_union(other, sort=sort)
        else:
           result = Index._union(this, other, sort=sort)
           if isinstance(result, type(self)):
               assert result._data.dtype == this.dtype
               if result.freq is None:
                   result._set_freq("infer")
           return result

   # --------------------------------------------------------------------
   # Join Methods
   _join_precedence = 10

   _inner_indexer = _join_i8_wrapper(libjoin.inner_join_indexer)
   _outer_indexer = _join_i8_wrapper(libjoin.outer_join_indexer)
   _left_indexer = _join_i8_wrapper(libjoin.left_join_indexer)
   _left_indexer_unique = _join_i8_wrapper(
       libjoin.left_join_indexer_unique, with_indexers=False
   )

   def join(
       self, other, how: str = "left", level=None, return_indexers=False, sort=False
   ):
        """
       See Index.join
        """
       if self._is_convertible_to_index_for_join(other):
           try:
               other = type(self)(other)
           except (TypeError, ValueError):
               pass

       this, other = self._maybe_utc_convert(other)
       return Index.join(
           this,
           other,
           how=how,
           level=level,
           return_indexers=return_indexers,
           sort=sort,
       )

   def _maybe_utc_convert(self, other):
       this = self
       if not hasattr(self, "tz"):
           return this, other

       if isinstance(other, type(self)):
           if self.tz is not None:
               if other.tz is None:
                   raise TypeError("Cannot join tz-naive with tz-aware DatetimeIndex")
           elif other.tz is not None:
               raise TypeError("Cannot join tz-naive with tz-aware DatetimeIndex")

           if not timezones.tz_compare(self.tz, other.tz):
               this = self.tz_convert("UTC")
               other = other.tz_convert("UTC")
       return this, other

   @classmethod
   def _is_convertible_to_index_for_join(cls, other: Index) -> bool:
       """
       return a boolean whether I can attempt conversion to a
       DatetimeIndex/TimedeltaIndex
       """
       if isinstance(other, cls):
           return False
       elif len(other) > 0 and other.inferred_type not in (
           "floating",
           "mixed-integer",
           "integer",
           "integer-na",
           "mixed-integer-float",
           "mixed",
       ):
           return True
       return False

   def _wrap_joined_index(self, joined, other):
       name = get_op_result_name(self, other)
       if (
           isinstance(other, type(self))
           and self.freq == other.freq
           and self._can_fast_union(other)
       ):
           joined = self._shallow_copy(joined)
           joined.name = name
           return joined
        else:
           kwargs = {}
           if hasattr(self, "tz"):
               kwargs["tz"] = getattr(other, "tz", None)
           return self._simple_new(joined, name, **kwargs)


class DatetimelikeDelegateMixin(PandasDelegate):
    """
   Delegation mechanism, specific for Datetime, Timedelta, and Period types.

   Functionality is delegated from the Index class to an Array class. A
   few things can be customized

   * _delegated_methods, delegated_properties : List
       The list of property / method names being delagated.
   * raw_methods : Set
       The set of methods whose results should should *not* be
       boxed in an index, after being returned from the array
   * raw_properties : Set
       The set of properties whose results should should *not* be
       boxed in an index, after being returned from the array
    """

   # raw_methods : dispatch methods that shouldn't be boxed in an Index
   _raw_methods: Set[str] = set()
   # raw_properties : dispatch properties that shouldn't be boxed in an Index
   _raw_properties: Set[str] = set()
   _data: ExtensionArray

   def _delegate_property_get(self, name, *args, **kwargs):
       result = getattr(self._data, name)
       if name not in self._raw_properties:
           result = Index(result, name=self.name)
       return result

   def _delegate_property_set(self, name, value, *args, **kwargs):
       setattr(self._data, name, value)

   def _delegate_method(self, name, *args, **kwargs):
       result = operator.methodcaller(name, *args, **kwargs)(self._data)
       if name not in self._raw_methods:
           result = Index(result, name=self.name)
       return result

