       result = s1.combine(val, lambda x1, x2: x1 <= x2)
       expected = pd.Series([a <= val for a in list(orig_data1)], dtype="boolean")
       self.assert_series_equal(result, expected)

   def test_searchsorted(self, data_for_sorting, as_series):
