       data_for_sorting = pd.array([True, False], dtype="boolean")
       b, a = data_for_sorting
       arr = type(data_for_sorting)._from_sequence([a, b])

       if as_series:
           arr = pd.Series(arr)
       assert arr.searchsorted(a) == 0
       assert arr.searchsorted(a, side="right") == 1

